namespace SCI_PH.Application.Abstractions.Storage
{
    // Object storage of document contents (Azure Blob in production). Only the Document Service uses it: BFFs never touch
    // the storage, and the path is always generated by the server, never taken from the client or the file name.
    // Failures to reach the storage surface as exceptions; the caller maps them to a generic 503.
    public interface IStorageService
    {
        // Writes the object; an existing object at the path is never overwritten (the path is new for every upload).
        Task UploadAsync(string path, ReadOnlyMemory<byte> content, string contentType, CancellationToken cancellationToken);

        // The object's content, or null when it does not exist.
        Task<Stream?> OpenReadAsync(string path, CancellationToken cancellationToken);

        // Best effort: removes the object if it exists (used to clean up after a failed metadata save).
        Task DeleteAsync(string path, CancellationToken cancellationToken);
    }
}
